arguments.command:
cd /tmp/sv-cea2e048b8b64445bf61c2558f96f745

# For the SGen worker addresses in .data.rel.ro, check what function they belong to
# using the dynamic symbol table from the .so
llvm-nm-18 --dynamic --defined-only libmonosgen-2.0.so 2>/dev/null | sort | awk '
{
  addr = strtonum("0x" $1)
  if (addr <= 0x2f4b20) { before1=$0 }
  if (addr <= 0x2f4c84) { before2=$0 }
  if (addr > 0x2f4c84 && !printed) { print "Before 0x2f4b20: " before1; print "Before 0x2f4c84: " before2; print "After: " $0; printed=1 }
}'

echo "---"
# These are in .data.rel.ro which is the interpreter dispatch table
# Let's look at what nm in the debug file says for these ranges
llvm-nm-18 --defined-only libmonosgen-2.0.so.dbg 2>/dev/null | sort | awk '
{
  addr = strtonum("0x" $1)
  if (addr <= 0x2f4b20) { before1_line=$0; before1_addr=addr }
  if (addr <= 0x2f4c84) { before2_line=$0; before2_addr=addr }
  if (addr > 0x2f4c84 && !printed) { 
    print "Nearest symbol before 0x2f4b20: " before1_line " (offset +" sprintf("0x%x", 0x2f4b20-before1_addr) ")"
    print "Nearest symbol before 0x2f4c84: " before2_line " (offset +" sprintf("0x%x", 0x2f4c84-before2_addr) ")"
    print "Next symbol after: " $0
    printed=1
  }
}'

